import{_ as t,o,c as a,a2 as n}from"./chunks/framework.sN6AQ-fu.js";const u=JSON.parse('{"title":"Robot","description":"","frontmatter":{},"headers":[],"relativePath":"suite/robot.md","filePath":"suite/robot.md"}'),r={name:"suite/robot.md"};function s(i,e,l,h,d,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="robot" tabindex="-1">Robot <a class="header-anchor" href="#robot" aria-label="Permalink to &quot;Robot&quot;">​</a></h1><p>The Robot workspace has five tabs.</p><h2 id="on-the-robot-now" tabindex="-1">On the robot now <a class="header-anchor" href="#on-the-robot-now" aria-label="Permalink to &quot;On the robot now&quot;">​</a></h2><p>What code the robot is running (desktop app, robot connected). It refreshes when the robot connects, or click <strong>Check robot</strong>.</p><ul><li>The commit and branch, when and by whom it was built, and <strong>same as main</strong> when it matches.</li><li>A warning if it was deployed with uncommitted changes, since nobody can rebuild exactly that version.</li><li>If it differs from <code>main</code>: the commits on the robot but not on main (with the task each one was for), how many newer commits are on main, and two buttons: <ul><li><strong>What&#39;s different from main</strong> opens <a href="/Mayhem/suite/changes">Changes</a> comparing them.</li><li><strong>Put main back on the robot</strong> builds main and deploys it after you confirm. The robot must be connected and disabled. Nothing in the repository changes.</li></ul></li><li>The health of the newest log: red flags and any flickering signals.</li></ul><p><code>main</code> is the known-good version.</p><h2 id="values" tabindex="-1">Values <a class="header-anchor" href="#values" aria-label="Permalink to &quot;Values&quot;">​</a></h2><p>Every value in the robot code: CAN IDs, current limits, ratios, gains, inversions, brake/coast and more. Narrow it by <strong>kind</strong> or by <strong>part</strong>, or search. Safety-related kinds are marked. Click the pencil next to a value to change it; Mayhem rewrites just that literal in the C++ on this computer. Review the edit on <a href="/Mayhem/suite/changes">Changes</a> before you commit.</p><h2 id="specs-limits" tabindex="-1">Specs &amp; limits <a class="header-anchor" href="#specs-limits" aria-label="Permalink to &quot;Specs &amp; limits&quot;">​</a></h2><p>The robot&#39;s length, width and drive limits that every auto is planned with, plus <strong>Slow down before slower steps</strong>. Lengths are in meters and angles in degrees here; exported code uses meters and radians.</p><p>The <strong>typed inputs</strong> (sensors, buttons, game state) that your routine conditions and state machines read are defined here too.</p><h2 id="connection" tabindex="-1">Connection <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;Connection&quot;">​</a></h2><p>Enter your team number, or an address override, and <strong>Connect</strong>. Values come in over read-only NT4; Mayhem never commands the robot. The browser version may not be allowed to connect to a robot from a hosted HTTPS page; use the desktop app.</p><p><strong>AdvantageScope:</strong> set the application path if it isn&#39;t detected automatically. Logs then get an <strong>Open in AdvantageScope</strong> button.</p><h2 id="log-collection" tabindex="-1">Log collection <a class="header-anchor" href="#log-collection" aria-label="Permalink to &quot;Log collection&quot;">​</a></h2><h3 id="automatic-log-collection-desktop" tabindex="-1">Automatic log collection (desktop) <a class="header-anchor" href="#automatic-log-collection-desktop" aria-label="Permalink to &quot;Automatic log collection (desktop)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Source</th><th>Use</th></tr></thead><tbody><tr><td><strong>Robot over Ethernet</strong></td><td>Pulls logs off the roboRIO over SFTP. Set the log folder on the robot (default <code>/home/lvuser/wpilogs</code>).</td></tr><tr><td><strong>Folder (simulation, USB)</strong></td><td>Watches a folder on this computer.</td></tr></tbody></table><p>List the files and <strong>Download selected</strong>, or turn on <strong>Take every new log</strong> (optionally only files whose names contain some text). It checks every 15 seconds while Mayhem is open and waits until a file stops growing. Collection keeps running whichever page you&#39;re on.</p><h3 id="team-upload" tabindex="-1">Team upload <a class="header-anchor" href="#team-upload" aria-label="Permalink to &quot;Team upload&quot;">​</a></h3><p>Enter the team website and a device upload token from the site&#39;s <strong>Logs → Connect Mayhem</strong>, then turn on <strong>Upload new logs automatically</strong>. New logs are queued and failed uploads retry. <strong>Remember the token on this computer</strong> keeps it across restarts; <strong>Pause uploads</strong> holds the queue. See <a href="https://github.com/ryanabraham1/Mayhem/blob/main/docs/TEAM_LOGS.md" target="_blank" rel="noreferrer">team log setup</a>.</p>',20)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
